    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.dir, True)
        for name, data in (("catalog.txt", self.catalog), ("movements.txt", self.movements), ("orders.txt", self.orders)):
            if data is not None:
                self.write(name, data)

    def path(self, name):
        return os.path.join(self.dir, name)

    def write(self, name, data):
        with open(self.path(name), "wb") as f:
            f.write(data if isinstance(data, bytes) else data.encode("utf-8"))

    def read(self, name):
        with open(self.path(name), "rb") as f:
            return f.read()

    def run_cli(self, *args, cwd=None):
        """Run ``stockroom.cli.main`` in-process with the given directory as cwd."""
        out, err = io.BytesIO(), io.BytesIO()
        saved = (sys.stdout, sys.stderr, os.getcwd())
        sys.stdout = types.SimpleNamespace(buffer=out)
        sys.stderr = types.SimpleNamespace(buffer=err)
        os.chdir(cwd or self.dir)
        try:
            code = cli.main(list(args))
        finally:
            sys.stdout, sys.stderr = saved[0], saved[1]
            os.chdir(saved[2])
        return Result(code, out.getvalue(), err.getvalue())

    def run_proc(self, *args, cwd=None, **extra_env):
        """Run ``python -m stockroom`` in a subprocess."""
        env = dict(os.environ, PYTHONPATH=ROOT, **extra_env)
        proc = subprocess.run(
            [sys.executable, "-m", "stockroom", *args],
            cwd=cwd or self.dir,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            stdin=subprocess.DEVNULL,
        )
        return Result(proc.returncode, proc.stdout, proc.stderr)

    def ok(self, *args):
        r = self.run_cli(*args)
        self.assertEqual((r.code, r.err), (0, ""), r.err)
        return r.out

    def fails(self, code, *args):
        before = {n: self.read(n) for n in os.listdir(self.dir)}
        r = self.run_cli(*args)
        self.assertEqual(r.code, code, (r.out, r.err))
        self.assertEqual(r.out, "")
        self.assertTrue(r.err.startswith("stockroom: "), r.err)
        self.assertEqual({n: self.read(n) for n in os.listdir(self.dir)}, before)
        return r.err
        self.fails(2, "stock", "--bogus")
        self.fails(2, "receive", "2024-13-01", "AB-100", "1")


class DirTests(CliCase):
    def test_dir_forms_anywhere(self):
        other = tempfile.mkdtemp()
        self.addCleanup(os.rmdir, other)
        expected = self.ok("stock")
        for args in (
            ("--dir", self.dir, "stock"),
            ("stock", "--dir", self.dir),
            ("--dir=" + self.dir, "stock"),
            ("stock", "--dir=" + self.dir),
            ("history", "--dir", self.dir, "AB-100"),
            ("--dir", other, "stock", "--dir", self.dir),
        ):
            with self.subTest(args=args):
                r = self.run_cli(*args, cwd=other)
                self.assertEqual((r.code, r.err), (0, ""))
                if args[0] != "history" and "history" not in args:
                    self.assertEqual(r.out, expected)

    def test_dir_for_receive_and_fulfil(self):
        other = tempfile.mkdtemp()
        self.addCleanup(os.rmdir, other)
        r = self.run_cli("receive", "2024-04-01", "AB-100", "2", "--dir", self.dir, cwd=other)
        self.assertEqual((r.code, r.out), (0, "2024-04-01 AB-100 +2\n"))
        r = self.run_cli("--dir", self.dir, "fulfil", "SO-1001", "2024-04-02", cwd=other)
        self.assertEqual(r.code, 0)
        self.assertEqual(os.listdir(other), [])

    def test_missing_dir_is_exit_2(self):
        err = self.fails(2, "stock", "--dir", os.path.join(self.dir, "nope"))
        self.assertIn("catalog.txt", err)

    def test_dir_is_not_a_directory(self):
        self.fails(2, "stock", "--dir", self.path("catalog.txt"))

    def test_last_dir_wins(self):
        self.ok("--dir", "/nonexistent-dir", "stock", "--dir", self.dir)
        self.fails(2, "--dir", self.dir, "stock", "--dir", "/nonexistent-dir")


